"""Generate clyphx/Macros.txt and clyphx/X-Controls.txt. python3 tools/gen_config.py
Note map (MIDI channel 16):
  36-47 source 1-12 | 48 prev | 49 next | 50 input off
  52-59 preset 1-8  | 60 rack chain prev | 61 rack chain next
  CC 20-23 looper REC / PLAY / UNDO / CLEAR (MIDI-map in Live, not ClyphX)"""
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
CH, MAX = 16, 12
SRC0, PREV, NEXT, OFF, PRE0, RPREV, RNEXT = 36, 48, 49, 50, 52, 60, 61

def macros():
    L = ["# livelooper companion - Macros (designed by groovex)",
         "# generated by tools/gen_config.py - install.command merges this block into",
         "# ~/nativeKONTROL/ClyphX_Pro/Macros.txt",
         "", "# Source select / Quelle waehlen (tracks left of LOOPER, max 12)"]
    L += [f"$LL_SRC{i}$ = LLSRC {i}" for i in range(1, MAX + 1)]
    L += ["$LL_PREV$ = LLSRC <", "$LL_NEXT$ = LLSRC >", "$LL_OFF$ = LLSRC OFF",
          "$LL_SETUP$ = LLSETUP 5", "",
          "# Presets of the armed synth: Program Change via IAC 'LL Synth'",
          "# (Pigments playlist; load Pigments as AU or VST2, not VST3)"]
    L += [f"$LL_PRE{i}$ = MIDI PC 1 {i - 1}" for i in range(1, 9)]
    L += ["", "# Instrument Rack chains (rack = device 1 on the selected track)",
          "$LL_RACK_PREV$ = SEL/DEV(1) CSEL <", "$LL_RACK_NEXT$ = SEL/DEV(1) CSEL >"]
    return "\n".join(L) + "\n"

def xcontrols():
    L = ["# livelooper companion - X-Controls (designed by groovex)",
         "# generated by tools/gen_config.py",
         "# Format: NAME = TYPE, CHANNEL, NOTE_OR_CC, OFF_LED, ON_LED, ON_ACTION_LIST",
         f"# All on MIDI channel {CH}. Stream Deck port: IAC 'LL Deck'.", ""]
    row = lambda n, num, m: f"{n} = NOTE, {CH}, {num}, 0, 127, ${m}$"
    L += [row(f"LL_SRC{i}", SRC0 + i - 1, f"LL_SRC{i}") for i in range(1, MAX + 1)]
    L += [row("LL_SRC_PREV", PREV, "LL_PREV"), row("LL_SRC_NEXT", NEXT, "LL_NEXT"),
          row("LL_SRC_OFF", OFF, "LL_OFF"), ""]
    L += [row(f"LL_PRE{i}", PRE0 + i - 1, f"LL_PRE{i}") for i in range(1, 9)]
    L += [row("LL_RACK_PREV", RPREV, "LL_RACK_PREV"), row("LL_RACK_NEXT", RNEXT, "LL_RACK_NEXT"), "",
          "# Looper transport: CC 20-23 on channel 16 -> MIDI-map in Live to livelooper."]
    return "\n".join(L) + "\n"

if __name__ == "__main__":
    (ROOT / "clyphx" / "Macros.txt").write_text(macros())
    (ROOT / "clyphx" / "X-Controls.txt").write_text(xcontrols())
    print("ok")
